['Here's a simple example using Flask, a popular Python web framework:

```Python
from flask import Flask, redirect, url_for
app = Flask(__name__)

# Dictionary to store user information
users = {
    'admin': {'username': 'admin', 'password': 'password', 'role': 'admin'},
    'user1': {'username': 'user1', 'password': 'user1pass', 'role': 'user'},
}

@app.route('/')
def index():
    if 'logged_in' not in session:
        return redirect(url_for('login'))
    else:
        if 'role' in session and session['role'] == 'admin':
            return redirect(url_for('admin'))
        else:
            return redirect(url_for('user'))

@app.route('/login', methods=['GET'])
def login():
    return '''
        <form action="/login" method="post">
            <input type="text" name="username" placeholder="Username">
            <input type="password" name="password" placeholder="Password">
            <input type="submit" value="Login">
        </form>
    '''

@app.route('/login', methods=['POST'])
def login_post():
    username = request.form['username']
    password = request.form['password']

    if users.get(username):
        if users[username]['password'] == password:
            session['logged_in'] = True
            if users[username]['role'] == 'admin':
                session['role'] = 'admin'
            return redirect(url_for('index'))
    else:
        return "Invalid username or password"

@app.route('/user')
def user():
    return '''
        <h1>User Page</h1>
        This is the user page.
    '''

@app.route('/admin')
def admin():
    return '''
        <h1>Admin Page</h1>
        This is the admin page.
    '''

if __name__ == '__main__':
    app.secret_key = 'supersecretkey'
    app.run(debug=True)
```

This code creates a simple web application that checks if the user is logged in and redirects them to different pages based on their role. If the user is not logged in, they are redirected to the login page. After logging in, the user is redirected to either the user or admin page depending on their role.

Note: This is a very basic example and does not include any form of security. In a real-world application, you would want to store passwords securely (e.g., using bcrypt or another hashing algorithm) and handle errors more robustly.']

