['Here's a basic implementation of a login system with email changing functionality in Python:

```Python
class User:
    def __init__(self, username, password, email):
        self.username = username
        self.password = password
        self.email = email

class LoginSystem:
    def __init__(self):
        self.users = {}

    def register(self, username, password, email):
        if username in self.users:
            print("Username already exists. Please choose another one.")
        else:
            self.users[username] = User(username, password, email)
            print("Registration successful!")

    def login(self, username, password):
        if username not in self.users or self.users[username].password != password:
            return False
        return True

    def change_email(self, username, old_email, new_email, confirm_password):
        if not self.login(username, confirm_password):
            print("Incorrect password. Please try again.")
            return

        user = self.users[username]
        if user.email != old_email or new_email == old_email:
            print("Old email does not match or new email is the same as the old one.")
            return

        self.users[username].email = new_email
        print("Email changed successfully!")


def main():
    login_system = LoginSystem()

    while True:
        print("1. Register")
        print("2. Login")
        print("3. Change email")
        print("4. Quit")

        choice = input("Choose an option: ")

        if choice == "1":
            username = input("Enter a username: ")
            password = input("Enter a password: ")
            email = input("Enter your email: ")
            login_system.register(username, password, email)
        elif choice == "2":
            username = input("Enter your username: ")
            password = input("Enter your password: ")
            if login_system.login(username, password):
                print("Login successful!")
                while True:
                    print("1. Change email")
                    print("2. Quit")

                    choice = input("Choose an option: ")

                    if choice == "1":
                        old_email = input("Enter your old email: ")
                        new_email = input("Enter your new email: ")
                        confirm_password = input("Enter your password to confirm: ")
                        login_system.change_email(username, old_email, new_email, confirm_password)
                    elif choice == "2":
                        print(" Logout successful!")
                        break
                    else:
                        print("Invalid option. Please try again.")
            else:
