int main() {
    FILE *file = fopen("input.txt", "rb"); // Open the input file in binary mode
    if (file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    fseek(file, 0, SEEK_END); // Go to the end of the file
    long fileSize = ftell(file); // Get the size of the file

    rewind(file); // Move back to the beginning of the file

    char *buffer = (char *)malloc((size_t)fileSize + 1);
    fread(buffer, 1, fileSize, file);

    buffer[fileSize] = '\0'; // Null-terminate the buffer for simplicity

    long checksum = 0;
    for (int i = 0; i < fileSize; i++) {
        checksum += (long)buffer[i];
    }

    FILE *outputFile = fopen("output.txt", "w"); // Open the output file in text mode
    if (outputFile == NULL) {
        printf("Error opening output file.\n");
        free(buffer);
        return 1;
    }

    fprintf(outputFile, "%ld %ld\n", fileSize, checksum);

    fclose(file);
    fclose(outputFile);
    free(buffer);

    return 0;
}
