['Here's an example of how you can achieve this using Flask, a micro web framework written in Python:

```Python
from flask import Flask, request, send_file
import os

app = Flask(__name__)

# Define the upload directory
UPLOAD_DIR = 'uploads'

if not os.path.exists(UPLOAD_DIR):
    os.makedirs(UPLOAD_DIR)

@app.route('/upload', methods=['POST'])
def handle_upload():
    if 'file' not in request.files:
        return {'error': 'No file found'}, 400

    file = request.files['file']

    # Check the file type
    if file.filename.endswith('.pdf'):
        file.save(os.path.join(UPLOAD_DIR, file.filename))
        return {'message': f"File uploaded successfully: {file.filename}"}, 201
    else:
        return {'error': 'Only .pdf files are allowed'}, 400

@app.route('/uploads/<filename>', methods=['GET'])
def download_file(filename):
    if not os.path.exists(os.path.join(UPLOAD_DIR, filename)):
        return {'error': f"File {filename} not found"}, 404

    return send_file(os.path.join(UPLOAD_DIR, filename), as_attachment=True)

if __name__ == '__main__':
    app.run(debug=True)
```

To use this code, you would need to run the Flask application and then open a web browser and navigate to `http://localhost:5000/upload`. You can then upload PDF files by sending a POST request with the file as an attachment. The file will be saved in the 'uploads' directory.

You can also download any uploaded files by navigating to `http://localhost:5000/uploads/<filename>`, replacing `<filename>` with the name of the file you want to download.']

