int run_command(char* username) {
    char* command = (char*)malloc(20);
    sprintf(command, "id %s", username);

    pid_t pid = fork();
    if (pid == 0) { // child process
        execl("/bin/sh", "-c", command, NULL);
        printf("Error running the command.\n");
        exit(EXIT_FAILURE);
    } else { // parent process
        int status;
        wait(&status); // wait for the child to finish
        free(command);
        return status; // return the exit status of the command
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int exit_status = run_command(argv[1]);

    printf("Exit status of the command: %d\n", exit_status);

    return EXIT_SUCCESS;
}
```

In this code, we use the `fork` function to create a new process that runs the specified command. The parent process waits for the child process to finish and then returns its exit status.

