// Function to execute the ls command with a given directory path
void exec_ls(const char *path) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        if (execlp("ls", "ls", "-l", "--color=always", path, NULL) == -1) {
            perror("execvp");
            exit(EXIT_FAILURE);
        }
    } else { // Parent process
