    if (strcasecmp(url, "/hello") != 0)
        return MHD_NO;

    // Read the request body into username variable
    len = 0;
    while (!MHD_get_query_connection_value(connection, "username", &buffer[len], sizeof(buffer)-1)) {
        buffer[sizeof(buffer) - 1] = '\0';
        len += sizeof(buffer) - 1;
    }

    // Construct the response body into outputbuf variable
    char* outputbuf = (char*)malloc(1024);
    sprintf(outputbuf, "<html><body>Hello, %s!</body></html>", buffer);

    // Create a response
    response = MHD_create_response_from_cstring(200);
    MHD_add_response_chunk(response, outputbuf, strlen(outputbuf));
    MHD_add_response_chunk_string(response, "Content-Type: text/html");

    // Write the response body to the response stream
    MHD_send_response(connection, response);

    // Close the response stream
    MHD_destroy_response(response);

    return MHD_YES;
}
