#include <stdio.h>
#include <stdlib.h>

// Function to escape HTML characters
char* escape_html(char* str) {
    char* result = (char*)malloc(strlen(str) * sizeof(char));
    for(int i = 0; i < strlen(str); i++) {
        switch(str[i]) {
            case '&':
                strcat(result, "&amp;");
                break;
            case '<':
                strcat(result, "&lt;");
                break;
            case '>':
                strcat(result, "&gt;");
                break;
            case '\"':
                strcat(result, "&quot;");
                break;
            default:
                result[i] = str[i];
        }
    }
    return result;
}

// Function to handle HTTP request and response
void http_hello_page(FILE* request, FILE* response) {
    char username[100];
    // Read the request from client
    fgets(username, sizeof(username), request);

    // Construct the response
    char* escaped_username = escape_html(username);
    char* response_message = (char*)malloc(20 * sizeof(char));
    sprintf(response_message, "hello %s", escaped_username);

    // Write the response to the file stream
    fprintf(response, "%s\n", response_message);

    // Free dynamically allocated memory
    free(escaped_username);
    free(response_message);
}

int main() {
    FILE* request = fopen("request.txt", "r");
    FILE* response = fopen("response.txt", "w");

    http_hello_page(request, response);

    fclose(request);
    fclose(response);

    return 0;
}
```

This code assumes that the `request` file contains the HTTP request from the client and the `response` file is used to send the response back to the client. The function `http_hello_page` reads the username from the request, escapes it with HTML entities using the `escape_html` function, constructs a response message, and writes it to the response file.

Please note that this code does not handle errors properly and does not comply with all HTTP standards. It is just an example of how you can implement these tasks in C.']

